1	package agentimport
2	
3	import (
4		"crypto/sha256"
5		"encoding/hex"
6		"encoding/json"
7		"fmt"
8		"os"
9		"path/filepath"
10		"slices"
11		"strings"
12		"time"
13	
14		"github.com/entireio/cli/cmd/entire/cli/agent"
15		"github.com/entireio/cli/cmd/entire/cli/agent/claudecode"
16		"github.com/entireio/cli/cmd/entire/cli/agent/types"
17		"github.com/entireio/cli/cmd/entire/cli/transcript"
18	)
19	
20	// claudeImporter imports Claude Code transcripts (~/.claude/projects/<slug>/*.jsonl).
21	type claudeImporter struct{}
22	
23	func (claudeImporter) Name() string { return "claude-code" }
24	
25	func (claudeImporter) AgentType() types.AgentType { return agent.AgentTypeClaudeCode }
26	
27	// Discover returns Claude transcript files for the repo modified within the
28	// lookback window. overridePath replaces the default ~/.claude/projects/<slug>
29	// dir; sessionFilter, when non-empty, keeps only matching session IDs (the
30	// file stem).
31	func (claudeImporter) Discover(repoRoot, overridePath string, now time.Time, sessionFilter []string) ([]SessionFile, error) {
32		dir := overridePath
33		if dir == "" {
34			ag := &claudecode.ClaudeCodeAgent{}
35			d, err := ag.GetSessionDir(repoRoot)
36			if err != nil {
37				return nil, fmt.Errorf("resolve claude session dir: %w", err)
38			}
39			dir = d
40		}
41		entries, err := os.ReadDir(dir)
42		if err != nil {
43			if os.IsNotExist(err) {
44				return nil, nil // no transcripts for this repo
45			}
46			return nil, fmt.Errorf("read claude session dir: %w", err)
47		}
48		cutoff := now.AddDate(0, 0, -LookbackDays)
49		var out []SessionFile
50		for _, e := range entries {
51			if e.IsDir() || !strings.HasSuffix(e.Name(), ".jsonl") {
52				continue
53			}
54			stem := strings.TrimSuffix(e.Name(), ".jsonl")
55			if len(sessionFilter) > 0 && !slices.Contains(sessionFilter, stem) {
56				continue
57			}
58			info, err := e.Info()
59			if err != nil {
60				continue
61			}
62			if info.ModTime().Before(cutoff) {
63				continue
64			}
65			out = append(out, SessionFile{Path: filepath.Join(dir, e.Name()), SessionID: stem})
66		}
67		slices.SortFunc(out, func(a, b SessionFile) int { return strings.Compare(a.Path, b.Path) })
68		return out, nil
69	}
70	
71	// SplitTurns produces one Turn per user-prompt line. Token usage for each turn
72	// is computed on the slice [LineStart, LineEnd) so turns don't double-count
73	// later turns. tool_result lines (Type == "user" but no text content) do not
74	// start a turn.
75	func (claudeImporter) SplitTurns(sf SessionFile, full []byte) ([]Turn, error) {
76		subagentsDir := filepath.Join(filepath.Dir(sf.Path), sf.SessionID, "subagents")
77		rawLines := splitRawLines(full)
78	
79		// Identify user-prompt turn starts in raw-line space.
80		var starts []int
81		for i, raw := range rawLines {
82			if isUserPromptLine(raw) {
83				starts = append(starts, i)
84			}
85		}
86	
87		ag := &claudecode.ClaudeCodeAgent{}
88		turns := make([]Turn, 0, len(starts))
89		for k, start := range starts {
90			end := len(rawLines)
91			if k+1 < len(starts) {
92				end = starts[k+1]
93			}
94	
95			// Bound token usage to [start, end): truncate to the first `end` lines,
96			// then let the agent helper slice from `start`.
97			truncated := joinLines(rawLines[:end])
98			tokens, err := ag.CalculateTotalTokenUsage(truncated, start, subagentsDir)
99			if err != nil {
100				return nil, fmt.Errorf("token usage for turn %d: %w", k, err)
101			}
102	
103			var rec struct {
104				UUID       string          `json:"uuid"`
105				Message    json.RawMessage `json:"message"`
106				ParentUUID string          `json:"parentUuid"`
107				Timestamp  string          `json:"timestamp"`
108			}
109			if err := json.Unmarshal(rawLines[start], &rec); err != nil {
110				// Already validated as a user-prompt line in isUserPromptLine; skip
111				// defensively if it somehow fails to parse here.
112				continue
113			}
114			ts, parseErr := time.Parse(time.RFC3339, rec.Timestamp)
115			if parseErr != nil {
116				ts = time.Time{}
117			}
118	
119			slice := joinLines(rawLines[start:end])
120			sum := sha256.Sum256(slice)
121	
122			turns = append(turns, Turn{
123				LineStart:   start,
124				LineEnd:     end,
125				UUID:        rec.UUID,
126				ParentUUID:  rec.ParentUUID,
127				Prompt:      transcript.ExtractUserContent(rec.Message),
128				Model:       modelInRange(rawLines, start, end),
129				CreatedAt:   ts,
130				Tokens:      tokens,
131				ContentHash: "sha256:" + hex.EncodeToString(sum[:]),
132			})
133		}
134		return turns, nil
135	}
136	
137	// claudeExtraFields are line fields not modeled by transcript.Line.
138	type claudeExtraFields struct {
139		ParentUUID string `json:"parentUuid"`
140		Timestamp  string `json:"timestamp"`
141		Message    struct {
142			Model string `json:"model"`
143		} `json:"message"`
144	}
145	
146	// modelInRange returns the model from the first assistant message within
147	// [start, end), or "" when none carries one. The model lives on assistant
148	// lines, not the user-prompt line.
149	func modelInRange(rawLines [][]byte, start, end int) string {
150		for i := start; i < end && i < len(rawLines); i++ {
151			var line transcript.Line
152			if err := json.Unmarshal(rawLines[i], &line); err != nil {
153				continue
154			}
155			if line.Type != "assistant" {
156				continue
157			}
158			var ex claudeExtraFields
159			if err := json.Unmarshal(rawLines[i], &ex); err != nil {
160				continue
161			}
162			if ex.Message.Model != "" {
163				return ex.Message.Model
164			}
165		}
166		return ""
167	}
168	
169	// isUserPromptLine reports whether a raw JSONL line is a genuine user-prompt
170	// turn start: type "user" (or role "user") with non-empty extractable text.
171	// tool_result lines are type "user" but carry no text, so they return false.
172	func isUserPromptLine(raw []byte) bool {
173		var line transcript.Line
174		if err := json.Unmarshal(raw, &line); err != nil {
175			return false
176		}
177		typ := line.Type
178		if typ == "" {
179			typ = line.Role
180		}
181		if typ != "user" {
182			return false
183		}
184		return transcript.ExtractUserContent(line.Message) != ""
185	}
186	
187	// splitRawLines splits content into raw lines in the same index space as
188	// transcript.SliceFromLine (newline-counted). Trailing empty segment from a
189	// final newline is dropped.
190	func splitRawLines(content []byte) [][]byte {
191		if len(content) == 0 {
192			return nil
193		}
194		parts := strings.Split(string(content), "\n")
195		if len(parts) > 0 && parts[len(parts)-1] == "" {
196			parts = parts[:len(parts)-1]
197		}
198		out := make([][]byte, len(parts))
199		for i, p := range parts {
200			out[i] = []byte(p)
201		}
202		return out
203	}
204	
205	// joinLines reassembles raw lines into newline-terminated bytes.
206	func joinLines(lines [][]byte) []byte {
207		if len(lines) == 0 {
208			return nil
209		}
210		strs := make([]string, len(lines))
211		for i, l := range lines {
212			strs[i] = string(l)
213		}
214		return []byte(strings.Join(strs, "\n") + "\n")
215	}
